<?php

declare(strict_types=1);
namespace Atlas\Platform\Resources\Editorial\Admin;
use Atlas\Platform\Core\Logging\Logger;use Atlas\Platform\Organizations\Services\CurrentOrganizationResolver;use Atlas\Platform\Resources\Editorial\EditorialQueueRepository;use Atlas\Platform\Resources\Editorial\EditorialService;use Throwable;
final class EditorialQueueAdminPage{private string$hook='';public function __construct(private EditorialQueueRepository$queue,private EditorialService$editorial,private CurrentOrganizationResolver$organizations,private Logger$logger){}public function register():void{$this->hook=(string)add_submenu_page('atlas',__('Review Queue','atlas-platform'),__('Review Queue','atlas-platform'),'atlas_review_resources','atlas-resource-review',[$this,'render']);}public function enqueue(string$hook):void{if($hook===$this->hook){wp_enqueue_style('atlas-preview',ATLAS_PLATFORM_URL.'assets/css/atlas-preview.css',[],ATLAS_PLATFORM_VERSION);}}public function transition():void{if(!current_user_can('atlas_review_resources')&&!current_user_can('atlas_publish_resources')){wp_die(esc_html__('You are not allowed to review resources.','atlas-platform'),'', ['response'=>403]);}check_admin_referer('atlas_editorial_transition');$to=sanitize_key(wp_unslash((string)($_POST['to']??'')));if($to==='published'&&!current_user_can('atlas_publish_resources')){wp_die(esc_html__('You are not allowed to publish resources.','atlas-platform'),'', ['response'=>403]);}$organization=$this->organizations->resolveForUser(get_current_user_id());try{$result=$this->editorial->transition(sanitize_text_field(wp_unslash((string)($_POST['version_id']??''))),$to,get_current_user_id(),$organization?->id,current_user_can('atlas_manage_atlas'),sanitize_text_field(wp_unslash((string)($_POST['idempotency_key']??''))));$notice=$result===null?'not-found':'updated';}catch(Throwable$failure){$this->logger->log('error','resources.admin_transition_failed','Resource editorial transition from administration failed.',[],'resources',$failure);$notice='failed';}wp_safe_redirect(add_query_arg(['page'=>'atlas-resource-review','atlas_notice'=>$notice],admin_url('admin.php')));exit;}public function render():void{if(!current_user_can('atlas_review_resources')&&!current_user_can('atlas_publish_resources')){wp_die(esc_html__('You are not allowed to review resources.','atlas-platform'),'', ['response'=>403]);}$organization=$this->organizations->resolveForUser(get_current_user_id());$items=$this->queue->findForContext($organization?->id,current_user_can('atlas_manage_atlas'));$notice=sanitize_key(wp_unslash((string)($_GET['atlas_notice']??'')));require ATLAS_PLATFORM_DIR.'templates/resources/review-queue.php';}}
